constexpr const ApiEntry* find(std::string_view api) noexcept {
    for (const auto& e : kApi) if (e.api == api) return &e;
    return nullptr;
}

constexpr const ClassEntry* find_class(std::string_view name) noexcept {
    for (const auto& c : kClasses) if (c.name == name) return &c;
    return nullptr;
}

// The offset table is sorted by class and offset; therefore all
// entries of one class are contiguous.
constexpr const FieldOffset* offsets_begin(std::string_view cls) noexcept {
    for (std::size_t i = 0; i < kFieldOffsets.size(); ++i)
        if (kFieldOffsets[i].cls == cls) return &kFieldOffsets[i];
    return nullptr;
}

constexpr std::size_t offsets_size(std::string_view cls) noexcept {
    const FieldOffset* first = offsets_begin(cls);
    if (!first) return 0;
    std::size_t n = 0;
    while (first + n < kFieldOffsets.data() + kFieldOffsets.size() &&
           (first + n)->cls == cls) ++n;
    return n;
}

struct CtorEntry {
    std::string_view cls;
    std::uint32_t ctor_rva;      // function in which the vptr is set
    std::uint32_t vptr_rva;      // position of the vtable reference within it
    std::uint16_t calls;         // found call sites (creations)
};

